// After initialize, the server response may include:
// Mcp-Session-Id: 9f86d081-884c-4d5a-9a1b-3b1c2e5a7f10

async function initializeSession(baseUrl) {
  const res = await fetch(baseUrl + '/mcp', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      jsonrpc: '2.0',
      id: 1,
      method: 'initialize',
      params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'demo-client', version: '1.0.0' } }
    })
  });

  const sessionId = res.headers.get('Mcp-Session-Id');
  if (!sessionId) {
    throw new Error('server did not issue a session id');
  }
  return sessionId;
}

async function callTool(baseUrl, sessionId, toolName, args) {
  return fetch(baseUrl + '/mcp', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Mcp-Session-Id': sessionId
    },
    body: JSON.stringify({
      jsonrpc: '2.0',
      id: 2,
      method: 'tools/call',
      params: { name: toolName, arguments: args }
    })
  });
}

class ClientSession:
    def __init__(self, server_name, transport, session_id=None):
        self.server_name = server_name
        self.transport = transport
        self.session_id = session_id
        self.capabilities = {}
        self.status = "initializing"

    def mark_ready(self, capabilities):
        self.capabilities = capabilities
        self.status = "ready"

const sessions = new Map();

function registerSession(serverName, sessionId, transport) {
  sessions.set(serverName, {
    serverName,
    sessionId,
    transport,
    status: 'ready',
    createdAt: Date.now()
  });
}

function getSession(serverName) {
  const session = sessions.get(serverName);
  if (!session) {
    throw new Error('no active session for server: ' + serverName);
  }
  return session;
}

async function closeSession(baseUrl, sessionId) {
  await fetch(baseUrl + '/mcp', {
    method: 'DELETE',
    headers: { 'Mcp-Session-Id': sessionId }
  });
  sessions.delete(sessionIdToServerName(sessionId));
}

function markSessionFailed(serverName) {
  const session = sessions.get(serverName);
  if (session) {
    session.status = 'failed';
    sessions.delete(serverName);
  }
}

async function connectAll(configs) {
  for (const cfg of configs) {
    const transport = await openTransport(cfg);
    const initResult = await sendInitialize(transport, cfg);
    const sessionId = cfg.transportType === 'http'
      ? initResult.headers.get('Mcp-Session-Id')
      : null;

    registerSession(cfg.serverName, sessionId, transport);
    console.log('session ready for', cfg.serverName, sessionId || '(stdio, no id needed)');
  }
}

